import { Component, Input, OnChanges } from '@angular/core';
import { IsActiveMatchOptions } from '@angular/router';

@Component({
    selector: 'espd-subnav',
    templateUrl: './subnav.component.html',
    styleUrls: ['./subnav.component.scss'],
    standalone: false
})
export class SubnavComponent implements OnChanges {

	public static defaultActiveMatchOptions: IsActiveMatchOptions = {
		fragment: 'ignored',
		matrixParams: 'ignored',
		paths: 'exact',
		queryParams: 'ignored'
	}

	@Input()
	public label?: string;

	@Input()
	public linkActiveOptions: Partial<IsActiveMatchOptions> = SubnavComponent.defaultActiveMatchOptions;

	private matchOptions = SubnavComponent.defaultActiveMatchOptions

	public ngOnChanges(): void {
		// This is a bit odd, but if the value is computed directly in the getter for isActiveMatchOptions, an infinite loop occurs
		this.matchOptions = { ...SubnavComponent.defaultActiveMatchOptions, ...this.linkActiveOptions };
	}

	public get isActiveMatchOptions(): IsActiveMatchOptions {
		return this.matchOptions;
	}
}
